target.css:
:root {
  --cream: #f5e9d0;
  --brown: #5c3a1e;
  --gold: #b8860b;
  --rust: #a0430a;
  --light-brown: #c8a97e;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
}

.intermission-card {
  background-color: var(--cream);
  border: 3px solid var(--brown);
  border-radius: 4px;
  width: 320px;
  padding: 0;
  outline: 2px solid var(--light-brown);
  outline-offset: -8px;
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 16px 20px 12px;
  background-color: var(--brown);
}

.card-title {
  font-size: 22px;
  font-weight: 900;
  letter-spacing: 4px;
  color: var(--cream);
  margin: 0;
}

.star {
  color: var(--gold);
  font-size: 16px;
}

.divider {
  height: 3px;
  background-color: var(--gold);
  margin: 0;
}

.card-body {
  padding: 16px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.show-name {
  font-size: 13px;
  font-weight: 700;
  color: var(--rust);
  letter-spacing: 1px;
  text-transform: uppercase;
  margin: 0;
  text-align: center;
}

.duration-label {
  font-size: 12px;
  color: var(--brown);
  margin: 0;
  text-align: center;
}

.timer-badge {
  background-color: var(--rust);
  color: var(--cream);
  font-size: 20px;
  font-weight: 900;
  letter-spacing: 3px;
  padding: 8px 20px;
  border-radius: 3px;
  border: 2px solid var(--brown);
  margin-top: 4px;
}

.card-footer {
  padding: 10px 20px;
  background-color: var(--brown);
  display: flex;
  justify-content: center;
}

.footer-text {
  font-size: 11px;
  color: var(--light-brown);
  letter-spacing: 1px;
  text-align: center;
  font-style: italic;
}
